record.field:
for invoice in records.filtered('last_payment'):
    down_payment = env["event.registration.task.rel"].search([('registration_id.down_payment_id', '=', invoice.id), ('task_id', '=', env.ref('website_switzerland.task_down_payment').id), ('done', '=', False)])
    if down_payment:
        down_payment.write({'done': True})
    trip_invoice = env["event.registration.task.rel"].search([('registration_id.trip_invoice_id', '=', invoice.id), ('task_id', '=', env.ref('website_switzerland.task_full_payment').id), ('done', '=', False)])
    if trip_invoice:
        trip_invoice.write({'done': True})
